package governedprosekit

import (
	"errors"
	"time"

	"github.com/geoffmilleraz/fathom/third_party/agentic-kit/foundations/llmclient"
)

// ErrSession identifies an invalid session, profile, document target or version.
var ErrSession = errors.New("governedprosekit: invalid session")

// ErrImpact identifies an impact plan or rebuild refused because the dependency
// closure is unknown, cyclic, incomplete, shrunk or held.
var ErrImpact = errors.New("governedprosekit: impact held")

const (
	// GoalRequired marks a hard requirement the generator cannot waive.
	GoalRequired = "required"
	// GoalAdvisory marks guidance that is exposed to generation but never blocks.
	GoalAdvisory = "advisory"

	// OriginProfile marks a goal supplied by the document-type profile (a floor).
	OriginProfile = "profile"
	// OriginSession marks a goal added by the session.
	OriginSession = "session"
	// OriginTask marks a task-local goal added by the session.
	OriginTask = "task"

	// ScopeDocument applies a goal to every generated node. Any other scope is a
	// section node ID and applies to that section's generated descendants.
	ScopeDocument = "document"
)

// Node kinds. Containers (document, section, list, table) are rendered
// deterministically from their children. Leaves are generated by the model and
// checked as factual by default.
const (
	// KindDocument is the single root container.
	KindDocument = "document"
	// KindSection is a container that groups headings and content.
	KindSection = "section"
	// KindList is a container of list items.
	KindList = "list"
	// KindTable is a container of captions and paragraphs.
	KindTable = "table"
	// KindHeading is a leaf label, the only kind that may be non-factual.
	KindHeading = "heading"
	// KindParagraph is a generated paragraph leaf.
	KindParagraph = "paragraph"
	// KindSentence is a generated sentence leaf.
	KindSentence = "sentence"
	// KindSummary is a generated leaf that must declare the nodes it summarizes.
	KindSummary = "summary"
	// KindListItem is a generated leaf under a list.
	KindListItem = "list-item"
	// KindCaption is a generated leaf under a table.
	KindCaption = "caption"
)

// Semantic edge kinds. Structural parent/order is separate (DocNode.ParentID).
const (
	// EdgeSummary means From summarizes To.
	EdgeSummary = "summary"
	// EdgeContext means From was exposed To's text.
	EdgeContext = "context"
)

// ProfileOrigin separates supplied data from a catalog-resolved definition.
// Kind "supplied" carries no catalog claim. Kind "catalog" binds the stable key,
// the complete definition digest and the resolved layer/grant evidence; the
// caller (not this package) performs the catalog resolution.
type ProfileOrigin struct {
	Kind             string   `json:"kind"`
	CatalogKey       string   `json:"catalog_key,omitempty"`
	DefinitionDigest string   `json:"definition_digest,omitempty"`
	LayerEvidence    []string `json:"layer_evidence"`
}

// Goal is a stable-identity requirement with an eligible evidence method.
type Goal struct {
	ID         string `json:"id"`
	Class      string `json:"class"`
	Statement  string `json:"statement"`
	Scope      string `json:"scope"`
	Method     string `json:"method"`
	Acceptance string `json:"acceptance"`
	Origin     string `json:"origin"`
}

// SectionSpec is profile-declared structure: an expected section and the fact
// families it may draw on. Fields are exposed to generation of its descendants.
type SectionSpec struct {
	ID           string   `json:"id"`
	Title        string   `json:"title"`
	Required     bool     `json:"required"`
	FactFamilies []string `json:"fact_families"`
	Guidance     string   `json:"guidance"`
}

// PresentationDefaults are profile defaults for audience, voice and level. A
// session records which fields it supplied itself and which came from here.
type PresentationDefaults struct {
	Audience       string `json:"audience"`
	Voice          string `json:"voice"`
	TechnicalLevel string `json:"technical_level"`
}

// DocumentTypeProfile is immutable, digested document-type data: expected
// sections, base goals (hard floors), defaults and variation rules. Taxonomies
// are caller/CUE data, never production constants. Freeform profiles use the same
// type and must still declare at least one required goal and one required section.
type DocumentTypeProfile struct {
	Key           string               `json:"key"`
	Version       string               `json:"version"`
	Origin        ProfileOrigin        `json:"origin"`
	Freeform      bool                 `json:"freeform"`
	Sections      []SectionSpec        `json:"sections"`
	Goals         []Goal               `json:"goals"`
	Defaults      PresentationDefaults `json:"defaults"`
	PermitExtra   bool                 `json:"permit_extra_sections"`
	Digest        string               `json:"digest"`
	DigestVersion string               `json:"digest_version"`
}

// ProfileRef pins an exact profile version and digest.
type ProfileRef struct {
	Key     string `json:"key"`
	Version string `json:"version"`
	Digest  string `json:"digest"`
}

// SessionInput is the caller-supplied intent for NewDocumentSession. Expected
// IDs are caller-owned and independent of the authored goal and structure lists.
type SessionInput struct {
	ID                 string               `json:"id"`
	Purpose            string               `json:"purpose"`
	Supplied           PresentationDefaults `json:"supplied"`
	Goals              []Goal               `json:"goals"`
	ExpectedGoalIDs    []string             `json:"expected_goal_ids"`
	ExpectedSectionIDs []string             `json:"expected_section_ids"`
	Constraints        []string             `json:"constraints"`
	Intent             string               `json:"intent"`
}

// DocumentSession is a versioned, digested intent record, not conversation
// history. Revision 1 has no Parent; later revisions name the parent digest.
// DefaultsFrom maps audience/voice/technical_level to "session" or the profile
// key that supplied the default. Goals are the effective merged set.
type DocumentSession struct {
	ID                 string               `json:"id"`
	Revision           int                  `json:"revision"`
	Parent             string               `json:"parent"`
	Purpose            string               `json:"purpose"`
	Profile            ProfileRef           `json:"profile"`
	Presentation       PresentationDefaults `json:"presentation"`
	DefaultsFrom       map[string]string    `json:"defaults_from"`
	Goals              []Goal               `json:"goals"`
	ExpectedGoalIDs    []string             `json:"expected_goal_ids"`
	ExpectedSectionIDs []string             `json:"expected_section_ids"`
	Constraints        []string             `json:"constraints"`
	Intent             string               `json:"intent"`
	Digest             string               `json:"digest"`
}

// NodeSpec declares one document node. Container kinds (document, section, list,
// table) carry no instruction and are rendered. Leaf kinds are generated with
// exactly the exposure declared here: FactIDs (or WholeInput for every input
// fact), ContextNodeIDs (neighbor text) and the goals that apply by scope or by
// GoalIDs. Summarizes declares a summary's contributing nodes and is required for
// KindSummary. SectionID optionally names the profile section whose spec is exposed.
type NodeSpec struct {
	ID             string   `json:"id"`
	Kind           string   `json:"kind"`
	ParentID       string   `json:"parent_id"`
	Order          int      `json:"order"`
	Instruction    string   `json:"instruction"`
	FactIDs        []string `json:"fact_ids"`
	WholeInput     bool     `json:"whole_input"`
	ContextNodeIDs []string `json:"context_node_ids"`
	Summarizes     []string `json:"summarizes"`
	GoalIDs        []string `json:"goal_ids"`
	SectionID      string   `json:"section_id"`
}

// Edge is a semantic dependency From -> To. Kind is EdgeSummary or EdgeContext.
type Edge struct {
	From string `json:"from"`
	To   string `json:"to"`
	Kind string `json:"kind"`
}

// DocumentSpec is the caller's structure: nodes plus independently expected
// semantic edges. A missing expected edge holds generation and reuse.
type DocumentSpec struct {
	ID            string     `json:"id"`
	Nodes         []NodeSpec `json:"nodes"`
	ExpectedEdges []Edge     `json:"expected_edges"`
}

// DocumentInput carries the authenticated principal and the exact fact cut.
type DocumentInput struct {
	Principal string `json:"principal"`
	Facts     []Fact `json:"facts"`
}

// DocumentTarget is the complete desired state of a document version.
type DocumentTarget struct {
	Session DocumentSession     `json:"session"`
	Profile DocumentTypeProfile `json:"profile"`
	Spec    DocumentSpec        `json:"spec"`
	Input   DocumentInput       `json:"input"`
}

// DocumentLimits bounds structure work; fact/byte/token bounds come from the
// embedded SourcedConfig limits.
type DocumentLimits struct {
	MaxNodes int `json:"max_nodes"`
	MaxDepth int `json:"max_depth"`
	MaxEdges int `json:"max_edges"`
	MaxGoals int `json:"max_goals"`
}

// DefaultDocumentLimits supplies a medium-document profile.
func DefaultDocumentLimits() DocumentLimits {
	return DocumentLimits{MaxNodes: 512, MaxDepth: 8, MaxEdges: 2048, MaxGoals: 64}
}

// DocumentConfig versions the engine. Model is caller-supplied identity.
type DocumentConfig struct {
	Sourced SourcedConfig  `json:"sourced"`
	Limits  DocumentLimits `json:"limits"`
}

// ManifestFact binds one exposed fact by ID and complete-fact digest.
type ManifestFact struct {
	ID     string `json:"id"`
	Digest string `json:"digest"`
}

// ManifestNode binds one exposed neighbor by ID and exact content digest.
type ManifestNode struct {
	ID            string `json:"id"`
	ContentDigest string `json:"content_digest"`
}

// ReadManifest records what a role actually saw. Role is "generation" or
// "review". Facts includes exposed-but-uncited facts. Generation manifests carry
// only declared exposure; review manifests carry the wider full-input set.
type ReadManifest struct {
	Role           string         `json:"role"`
	NodeID         string         `json:"node_id"`
	Facts          []ManifestFact `json:"facts"`
	WholeInput     bool           `json:"whole_input"`
	Context        []ManifestNode `json:"context"`
	GoalsDigest    string         `json:"goals_digest"`
	SessionDigest  string         `json:"session_digest"`
	SectionDigest  string         `json:"section_digest"`
	ProfileDigest  string         `json:"profile_digest"`
	ConfigDigest   string         `json:"config_digest"`
	TemplateDigest string         `json:"template_digest"`
	Instruction    string         `json:"instruction_digest"`
	TextDigest     string         `json:"text_digest"`
	Digest         string         `json:"digest"`
}

// GenerationRecord records the configured requested model and completion counters.
// The shared client response cannot prove resolved model or usage-field presence.
// UsageState is unqualified; zero counters must never be interpreted as measured
// free usage. A separate bound transport receipt can qualify those observations.
type GenerationRecord struct {
	UsageState   string `json:"usage_state"`
	Attempt      int    `json:"attempt"`
	Model        string `json:"model"`
	StopReason   string `json:"stop_reason"`
	InputTokens  int    `json:"input_tokens"`
	OutputTokens int    `json:"output_tokens"`
	PromptDigest string `json:"prompt_digest"`
}

// DocNode is an immutable node in a version. ParentID/Order are structure.
// ContentDigest identifies bytes and claims; Version also binds the manifests and
// support, so provenance/review changes alter Version but not ContentDigest.
// Leaves carry Text, Claims and Ranges. Reused marks bytes carried exactly from
// the parent version.
type DocNode struct {
	ID            string                     `json:"id"`
	Kind          string                     `json:"kind"`
	ParentID      string                     `json:"parent_id"`
	Order         int                        `json:"order"`
	Text          string                     `json:"text"`
	Claims        []ProseClaim               `json:"claims"`
	Ranges        []ClaimRange               `json:"ranges"`
	NonFactual    string                     `json:"non_factual_reason"`
	Support       map[string]SupportDecision `json:"support"`
	GenManifest   *ReadManifest              `json:"gen_manifest"`
	ReviewMan     *ReadManifest              `json:"review_manifest"`
	Generation    *GenerationRecord          `json:"generation"`
	Reused        bool                       `json:"reused"`
	ContentDigest string                     `json:"content_digest"`
	Version       string                     `json:"version"`
}

// GoalBinding reports structural coverage of a goal: which generated nodes it
// was exposed to. Semantic acceptance is not assessed here (Assessed is always
// false); a required goal bound to no node refuses generation.
type GoalBinding struct {
	GoalID   string   `json:"goal_id"`
	Class    string   `json:"class"`
	Nodes    []string `json:"nodes"`
	Assessed bool     `json:"assessed"`
}

// DocumentReceipt binds a version to its session, profile, config and evidence.
// It is not a signature or consent: a changed session, profile, source cut or
// config changes DocumentDigest, so prior approval cannot bind to it.
type DocumentReceipt struct {
	Version        string    `json:"version"`
	DocumentDigest string    `json:"document_digest"`
	SessionDigest  string    `json:"session_digest"`
	ProfileDigest  string    `json:"profile_digest"`
	ConfigDigest   string    `json:"config_digest"`
	EvidenceDigest string    `json:"evidence_digest"`
	CheckedAt      time.Time `json:"checked_at"`
	Integrity      string    `json:"integrity"`
}

// DocumentVersion is an immutable, digest-sealed document. Parent is the prior
// version's digest ("" for the first). Callers must treat it as read-only;
// VerifyDocument detects mutation.
type DocumentVersion struct {
	Number  int             `json:"number"`
	Parent  string          `json:"parent"`
	Target  DocumentTarget  `json:"target"`
	Nodes   []DocNode       `json:"nodes"`
	Edges   []Edge          `json:"edges"`
	Goals   []GoalBinding   `json:"goals"`
	Receipt DocumentReceipt `json:"receipt"`
}

// SourceRebind declares that From and To are equivalent for one fact: identical
// value bytes under a new source revision. Equivalence and Actor are required,
// auditable statements; they do not freshen provenance (the rebuild re-resolves
// the To source and re-reviews every affected node).
type SourceRebind struct {
	FactID      string    `json:"fact_id"`
	From        SourceRef `json:"from"`
	To          SourceRef `json:"to"`
	Equivalence string    `json:"equivalence"`
	Actor       string    `json:"actor"`
}

// NodeImpact is one node's planned treatment and the reasons for it.
type NodeImpact struct {
	NodeID  string   `json:"node_id"`
	Reasons []string `json:"reasons"`
}

// ImpactPlan partitions nodes. Regenerate calls the model. Rerender rebuilds a
// container from children. Rebind keeps words, re-resolves and re-reviews against
// a declared equivalent source. ReviewAgain keeps words and re-reviews because the
// review read set changed. Reuse keeps bytes, provenance and review. Hold blocks.
type ImpactPlan struct {
	Regenerate  []NodeImpact `json:"regenerate"`
	Rerender    []NodeImpact `json:"rerender"`
	Rebind      []NodeImpact `json:"rebind"`
	ReviewAgain []NodeImpact `json:"review_again"`
	Reuse       []string     `json:"reuse"`
	Hold        []NodeImpact `json:"hold"`
	Removed     []string     `json:"removed"`
}

// RebuildOptions lets a caller or semantic judge propose a closure. A non-nil
// Requested set must contain the deterministic Regenerate floor or the rebuild is
// refused. SemanticWiden adds leaf nodes (and their dependents); it never removes.
type RebuildOptions struct {
	Requested     []string `json:"requested"`
	SemanticWiden []string `json:"semantic_widen"`
}

// DocumentDelta separates changed words from changed provenance/review.
// Fractions are numerator over the stated denominator (leaf nodes in the new version).
type DocumentDelta struct {
	WordsChanged      []string `json:"words_changed"`
	ProvenanceChanged []string `json:"provenance_changed"`
	Added             []string `json:"added"`
	Removed           []string `json:"removed"`
	RegeneratedLeaves int      `json:"regenerated_leaves"`
	LeafTotal         int      `json:"leaf_total"`
	ModelCalls        int      `json:"model_calls"`
	BytesChanged      int      `json:"bytes_changed"`
	BytesTotal        int      `json:"bytes_total"`
}

// RebuildResult is the new version with the plan executed and its delta.
type RebuildResult struct {
	Version DocumentVersion `json:"version"`
	Plan    ImpactPlan      `json:"plan"`
	Delta   DocumentDelta   `json:"delta"`
}

// NodeInspection exposes one node's metadata for the lab/UI without mutation.
type NodeInspection struct {
	Node         DocNode  `json:"node"`
	Dependencies []Edge   `json:"dependencies"`
	Dependents   []Edge   `json:"dependents"`
	Goals        []string `json:"goals"`
}

// SpanMapEntry ties rendered Markdown bytes [Start, End) to a node.
type SpanMapEntry struct {
	NodeID string `json:"node_id"`
	Start  int    `json:"start"`
	End    int    `json:"end"`
}

// RenderedDocument is deterministic Markdown with a node span map.
type RenderedDocument struct {
	Markdown       string         `json:"markdown"`
	MarkdownDigest string         `json:"markdown_digest"`
	DocumentDigest string         `json:"document_digest"`
	SpanMap        []SpanMapEntry `json:"span_map"`
}

// DocumentEngine generates and rebuilds session-governed documents over the
// strict SourcedPipeline checks. It holds no per-run state; calls are safe for
// concurrent use only if the injected client, sources, reviewer and clock are.
type DocumentEngine struct {
	pipe   *SourcedPipeline
	client llmclient.LLMClient
	cfg    DocumentConfig
	now    func() time.Time
}
